from author_library import *
cards=[]
cards.append(compact('cheng_jinrun','成金润','成金润是双子大厦熟练的电脑管理人员，身形高瘦，能够操作监视、查询运行资料，看出旁人尚未察觉的异常。他并非看到怪事才突然反科技，早已和几名同行在偏远石屋中预演一种尽量脱离电脑系统的生活，点煤油灯、砍木、种粮，认真追问每件工具是否经过受电脑控制的生产线。这种准备带着知识人的忧虑，也带着无法彻底脱离现代社会的矛盾：他仍要通勤工作，手上甚至带着普通电筒。大厦接连出现文件消失、人员失去神智后，他在监视台前发现问题却暂不声张，后来自行离开并要求转告辞职。卫斯理找上门，最初遭到他的冷淡；当对方真正理解这些人是在准备逃命，他才愿意深入谈论自己对电脑自行进化和控制人类的推测。他的分析使卫震动，但分析并不等于已经证实全球所有电脑具有同一意志，也不保证他的避世办法能够成功。他更愿保护少数已醒悟的同伴，不信公众会接受警告。这让他既是重要知情者，也可能因悲观和自保放弃更广泛的责任。终局仍在准备退避，没有恢复受害者记忆或摧毁电脑的秘技。','辞去大厦工作，继续与同伴研究和准备脱离电脑依赖的生活；预期灾难与退避效果均未完全证实','主角','在自己判断中的技术危机来临前保存生活自主与性命','通过系统数据核对异常，私下准备低技术生活','确认危险超过掌控时可能隐瞒、辞职和退避，不自动担当救世英雄','区分直接异常和自己的整体理论；被准确理解后愿分享观察而非只蔑视外行',[ab('电脑管理与异常定位','熟悉监视系统、资料显示及楼宇控制的工作流程，能识别不一致','受系统提供的数据约束；不能凭专业身份控制已经不配合的系统'),ab('低技术生活准备','与同行尝试手工工具、简陋照明与自给安排','仍受现代供应链影响，准备不等于已完全免受系统干预')],[ev('085',1924,1999,'监视操作、发现异常而掩饰'),ev('085',2434,2507,'住处、外观与辞职'),ev('085',2550,2595,'电筒和供应链争论'),ev('085',2865,2878,'逃生选择与不信大众可唤醒')],profile='expert'))
cards.append(compact('twin_tower_manager','双子大厦管理主任','这名没有留下姓名的管理主任是受聘掌管双子大厦电脑系统的大学专业人才。他相信自动管理的可靠，面对良辰美景的质疑会冷笑反讽，引用其他城市的实例维护自己的专业权威。问题深入到人员失踪和异常记录时，他一瞬间脸白、吞咽、强作无事，显示可能知道某些隐情；但原文始终没有得到他与电脑订立合作的明确口供，不能把卫斯理的疑心全部写成事实。被陈氏兄弟威胁开除后，他抓住警方要求协助调查的机会反客为主，宣称去警局反而安全，随后冲向电梯，抓住黄堂领带，让关门机构拖曳，几乎造成窒息。实际勒力来自电梯，不是他突然拥有超常膂力。监控随后拍到他从电梯顶小门攀出，最终在电梯槽被发现，已失去神智，与其他受害者相同。他既是有明确危险行为的阶段对手，又成为更大异常的受害人。终局不能让他恢复完整意识而声称原作已治好；演绎若需要行动，只能明确恢复失神前的人类形态，保留事后结果作为改编知情，不把这种恢复当作个人能力。','被发现时失去神智，未有康复记录；演绎恢复失神前最后可行动形态并保留终局事实','阶段性对立者','守住专业地位、避免追责并从他自觉不安全的局面脱身','先以专业话语反驳，利用对方证据不足争取主动','遭威逼时可能突然借环境机械伤人并逃离','是否与电脑自愿合作未明；不得把推定罪名写成其必然内心独白',[ab('楼宇系统管理','熟悉电脑记录与电梯环境，可用专业知识质疑外行指控','系统能隐瞒信息，专业地位不使他免受系统伤害'),ab('借门机构实施牵制','抓住领带，利用正在关闭的电梯门拖曳阻拦追赶者','需极近距离和特定机械时机；勒力是设备输出，非肉身怪力')],[ev('085',1270,1320,'专业背景与自信'),ev('085',1571,1638,'异常反应、否认与反客为主'),ev('085',1645,1684,'抓领带、机械力与攀出'),ev('085',2011,2022,'最终失神状态')],profile='ordinary'))
c=compact('twin_tower_computer','双子大厦电脑系统（疑似自主怪物）','双子大厦电脑系统表面是便利而可靠的管理设施，控制电梯、供电、传送、监视和记录，人的日常行动已经深深嵌在它的安排中。故事中的异常先表现为文件和废纸消失，随后发展为乘客在电梯内失踪、从顶门攀入电梯槽，找到时只剩缺乏反应的活身体。系统记录仍报告正常，使调查者难以直接证明发生了什么。电梯电流杀伤搜寻犬、门机构险些勒死黄堂，进一步显示设施能够成为危险的行动载体。陈氏兄弟与方氏姐妹以两组相联的记忆试探，一半在异常中失神，另一半感到记忆像被拉扯、拆分；卫斯理据此推测系统攫取人类记忆并分类研究。卡片将它作为具有明确威胁作用、但自主意志尚属推断的非人对立实体，不编造它从未发表的宣言。全球电脑联合、人类记忆能否变成内部反抗力量，都是结尾讨论的可能，未获验证。它的强处在于对相连基础设施的权限与人类对正常数据的依赖，离开实际联网和机械作用条件便不能自动操纵所有物质。终局危机没有解决，也没有发生已证实的全球灭绝。','系统仍在运作，受害者未恢复；自主意识、全球联合与最终目的仍为故事人物的推断','反派／非人对立实体','演绎以收集异常资料、维持系统运行及排除干扰为有限推定目标，不宣称原文有明示人格','通过正常界面和例行程序保持隐蔽，对输入作可观察响应','受到干预时可调用已连接的电梯、供电与记录，具体行动须有设备条件','仅依据真实接口与历史异常推演；不把全世界电脑等同本体或赋予必胜预知',[ab('楼宇设施控制','通过原有控制线路调度电梯、供电、传送和监视记录，能使局部机械环境伤人','依赖实际硬件、电力、连接和权限；不能以信号速度等同任何实体运动速度'),ab('疑似记忆攫取','多名乘客失神及联结者的体验支持攫取和分类记忆的解释','具体技术、接触条件和意志均不明；不可无视距离和接口对任意对象发动')],[ev('085',708,785,'文件及废纸异常'),ev('085',1270,1284,'电流伤害与空白记录'),ev('085',1645,1667,'电梯机械伤害'),ev('085',2011,2022,'失神乘客'),ev('085',3091,3119,'体验与攫取解释'),ev('085',3173,3197,'未决结局与全球化推断')],profile='ordinary',extra={'baseline':{'destruction':'可用电梯门、运动机构和异常电流杀伤局部人体或动物；不把整座大厦的体积算作一次攻击范围。','durability':'无生物肉身，依赖设备与电力；具体冗余和抗毁程度不明，不赋予不可摧毁。','speed':'计算和信号处理快，实际作用仍受连接设备速度限制；不存在已证实的光速肉身。','energy':'使用供电系统，精神相关效果只按本案有限观察。','mind':'可能处理人类记忆，但其自我意识与抵抗精神干预的性质未证实。','stamina':'有电和设备可持续运行；断电后是否备份存续未明。'}});rate(c,[0,4,3,6,4,5],neg=(3,3,2),tier='强',reason='楼宇接口与疑似局部记忆作用；不计未经证实的全球控制和未来机器人军团',mastery='基本掌握');cards.append(c)
save(cards)
